using DentalDashboard.Domain.PatientReferrals; using Microsoft.EntityFrameworkCore; using Microsoft.EntityFrameworkCore.Metadata.Builders;
namespace DentalDashboard.Infrastracture.Configuration;
public sealed class PatientReferralConfiguration:IEntityTypeConfiguration<PatientReferral>{public void Configure(EntityTypeBuilder<PatientReferral>b){b.ToTable("PatientReferrals");b.HasQueryFilter(x=>!x.IsDeleted);b.Property(x=>x.ReferredFirstName).IsRequired().HasMaxLength(100);b.Property(x=>x.ReferredLastName).IsRequired().HasMaxLength(100);b.Property(x=>x.ReferredPhoneNumber).IsRequired().HasMaxLength(11);b.Property(x=>x.Description).HasMaxLength(500);b.Property(x=>x.RejectionReason).HasMaxLength(500);b.Property(x=>x.RewardAmount).HasPrecision(18,2);b.HasIndex(x=>new{x.ReferrerPatientUserId,x.CreatedAt});b.HasIndex(x=>new{x.Status,x.CreatedAt});b.HasIndex(x=>x.ReferredPhoneNumber);b.HasIndex(x=>x.SecretaryUserId);b.HasIndex(x=>x.ReviewedByAdminId);b.HasIndex(x=>x.ReservationId);b.HasOne(x=>x.ReferrerPatientUser).WithMany().HasForeignKey(x=>x.ReferrerPatientUserId).OnDelete(DeleteBehavior.Restrict);b.HasOne(x=>x.SecretaryUser).WithMany().HasForeignKey(x=>x.SecretaryUserId).OnDelete(DeleteBehavior.Restrict);b.HasOne(x=>x.ReviewedByAdmin).WithMany().HasForeignKey(x=>x.ReviewedByAdminId).OnDelete(DeleteBehavior.Restrict);b.HasOne(x=>x.LeadAssignment).WithMany().HasForeignKey(x=>x.LeadAssignmentId).OnDelete(DeleteBehavior.Restrict);b.HasOne(x=>x.Reservation).WithMany().HasForeignKey(x=>x.ReservationId).OnDelete(DeleteBehavior.Restrict);}}
public sealed class PatientWalletConfiguration:IEntityTypeConfiguration<PatientWallet>{public void Configure(EntityTypeBuilder<PatientWallet>b){b.ToTable("PatientWallets",t=>t.HasCheckConstraint("CK_PatientWallets_Balance","[Balance] >= 0"));b.HasQueryFilter(x=>!x.IsDeleted);b.Property(x=>x.Balance).HasPrecision(18,2);b.HasIndex(x=>x.PatientUserId).IsUnique().HasFilter("[IsDeleted] = 0");b.HasOne(x=>x.PatientUser).WithMany().HasForeignKey(x=>x.PatientUserId).OnDelete(DeleteBehavior.Restrict);}}
public sealed class PatientWalletTransactionConfiguration:IEntityTypeConfiguration<PatientWalletTransaction>{public void Configure(EntityTypeBuilder<PatientWalletTransaction>b){b.ToTable("PatientWalletTransactions",t=>t.HasCheckConstraint("CK_PatientWalletTransactions_Amount","[Amount] > 0"));b.HasQueryFilter(x=>!x.IsDeleted);b.Property(x=>x.Amount).HasPrecision(18,2);b.Property(x=>x.Description).IsRequired().HasMaxLength(500);b.HasIndex(x=>new{x.PatientUserId,x.CreatedAt});b.HasIndex(x=>new{x.PatientReferralId,x.TransactionType}).IsUnique();b.HasOne(x=>x.Wallet).WithMany(x=>x.Transactions).HasForeignKey(x=>x.WalletId).OnDelete(DeleteBehavior.Restrict);b.HasOne(x=>x.PatientUser).WithMany().HasForeignKey(x=>x.PatientUserId).OnDelete(DeleteBehavior.Restrict);b.HasOne(x=>x.PatientReferral).WithMany().HasForeignKey(x=>x.PatientReferralId).OnDelete(DeleteBehavior.Restrict);}}
